def solution() -> int:
    C = [[18, 15], [7, 21]]
    n = len(C)
    full_mask = 1 << n
    dp = [float('inf')] * full_mask
    dp[0] = 0
    for mask in range(full_mask):
        worker = mask.bit_count()
        if worker >= n:
            continue
        for task in range(n):
            if not (mask & (1 << task)):
                new_mask = mask | (1 << task)
                dp[new_mask] = min(dp[new_mask], dp[mask] + C[worker][task])
    return int(dp[full_mask - 1])

