def solution():
    from heapq import heappush, heappop
    from collections import defaultdict

    edges = [
        (4, 2, 3),
        (3, 4, 1),
        (2, 0, 2),
        (0, 1, 2),
        (3, 2, 2),
        (2, 1, 4)
    ]

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    start, target = 0, 4
    heap = [(0, start)]
    dist = {start: 0}
    prev = {start: None}

    while heap:
        cur_dist, node = heappop(heap)
        if node == target:
            break
        if cur_dist > dist.get(node, float('inf')):
            continue
        for nei, w in graph[node]:
            nd = cur_dist + w
            if nd < dist.get(nei, float('inf')):
                dist[nei] = nd
                prev[nei] = node
                heappush(heap, (nd, nei))

    path = []
    node = target
    if node not in prev and node != start:
        return [], -1
    while node is not None:
        path.append(node)
        node = prev.get(node)
    path.reverse()

    return path, dist.get(target, -1)

