        (3, 4): 108
    }

    def d(i, j):
        if i == j:
            return 0
        return dist.get((i, j), dist.get((j, i)))

    start = 0
    others = [n for n in nodes if n != start]
    best_path = []
    best_cost = float('inf')

    for perm in permutations(others):
        path = [start] + list(perm) + [start]
        cost = sum(d(path[i], path[i + 1]) for i in range(len(path) - 1))
        if cost < best_cost:
            best_cost = cost
            best_path = path

