def solution() -> dict:
    from collections import deque

    # adjacency list representation of the graph
    adjacency = {
        1: [2, 3],
        2: [1, 5, 6],
        3: [1, 5, 6],
        4: [6],
        5: [2, 3],
        6: [2, 3, 4]
    }

    colors = {}
    color_labels = {0: 'A', 1: 'B'}

    for start in adjacency:
        if start in colors:
            continue
        queue = deque([start])
        colors[start] = 0

        while queue:
            node = queue.popleft()
            for neighbor in adjacency[node]:
                if neighbor not in colors:
                    colors[neighbor] = 1 - colors[node]
                    queue.append(neighbor)
                elif colors[neighbor] == colors[node]:
                    raise ValueError("Graph is not bipartite with 2 colors")

    return {vertex: color_labels[color] for vertex, color in colors.items()}

